import {CIRCUIT} from './tapeout.mjs';
import {RISK_POLICY} from './risk-rules.mjs';
const u24=n=>n.toString(16).padStart(6,'0');
// TAP-02 draft: 0x02 | cpu:20 | id:u64 | nIns:u8 | nOuts:u8 | ins:u24[].
export function riskCircuitDraft(){const wires=[[0,1],[3,3],[4,2],[5,5]],reference=(a,b)=>'02'+CIRCUIT.address.slice(2)+CIRCUIT.id.toString(16).padStart(16,'0')+'0201'+u24(a)+u24(b);return {schema:'moneylab-risk-circuit-draft.v1',status:'NOT_DEPLOYED',policy:RISK_POLICY,nIn:3,nOut:1,nState:0,inputs:['R','C','D'],netlist:'0x'+wires.map(([a,b])=>reference(a,b)).join(''),netlistBytes:148,topLevelNAND:0,topLevelLATCH:0,referenceCount:4,expandedGateCount:12,reference:{...CIRCUIT},wires,scope:'Design export only. Four REF records reuse existing circuit #48. Registration, deployed semantics, fees and transistor requirements must be simulated on the target chain before any tape-out. No gas or price estimate is promised.',spec:'https://github.com/TapeOutProtocol/TAPs/blob/main/TAPs/TAP-02.md'};}
export function evaluateDraft(bits,proof){const d=riskCircuitDraft();if(!Array.isArray(bits)||bits.length!==3||!bits.every(x=>x===0||x===1))throw Error('BITS_INVALID');const signals=[...bits];for(const [a,b] of d.wires){const receipt=proof.cases.find(c=>c.IN0===signals[a]&&c.IN1===signals[b]);if(!receipt)throw Error('MISSING_REFERENCE');signals.push(receipt.OUT0);}return signals.at(-1);}
